from flask import Flask, request, jsonify, redirect, url_for, make_response, abort
app = Flask(__name__)
@app.get("/start")
def start():
    return redirect(url_for("hello"))
@app.get("/hello")
def hello():
    return "Welcome"
if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8000)
